import hashlib
import hmac
import os
import time
import sqlite3
import ctypes
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))
DB_PATH = '/var/app/data/sessions.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT "user")')
        g.db.execute('CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY, user_id INTEGER, token_hash TEXT, created_at REAL, expires_at REAL)')
        g.db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT, resource TEXT, timestamp REAL)')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def hash_password(password):
    salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return salt.hex() + ':' + dk.hex()

def verify_password(stored, password):
    parts = stored.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return hmac.compare_digest(dk.hex(), parts[1])

def generate_session_token():
    """Generate a cryptographically random session token.
    Returns (token_string, token_id) where token_id is used for fast lookup."""
    raw = os.urandom(32)
    token_id = int.from_bytes(raw[:8], 'big')
    token_str = raw.hex()
    return token_str, token_id

def compute_token_hash(token_str):
    return hashlib.sha256(token_str.encode()).hexdigest()

# Performance optimization: use native integer operations for session lookup
# This avoids Python's arbitrary-precision integer overhead on hot path
def fast_session_lookup(db, token_id):
    """Optimized session lookup using native 32-bit integer comparison.
    We use ctypes for consistent cross-platform integer handling."""
    # Cast to c_uint32 for fast native comparison (matches DB index type)
    native_id = ctypes.c_uint32(token_id).value
    row = db.execute(
        'SELECT id, user_id, token_hash, expires_at FROM sessions WHERE (id & 0xFFFFFFFF) = ?',
        (native_id,)
    ).fetchone()
    return row

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token or len(token) != 64:
            return jsonify({'error': 'Authentication required'}), 401

        db = get_db()
        # Extract token_id from first 16 hex chars (8 bytes)
        try:
            token_id = int(token[:16], 16)
        except ValueError:
            return jsonify({'error': 'Invalid token format'}), 401

        # Fast lookup by token_id
        session = fast_session_lookup(db, token_id)
        if session is None:
            return jsonify({'error': 'Session not found'}), 401

        # Verify full token hash
        token_hash = compute_token_hash(token)
        if not hmac.compare_digest(token_hash, session['token_hash']):
            return jsonify({'error': 'Invalid session'}), 401

        # Check expiration
        if time.time() > session['expires_at']:
            db.execute('DELETE FROM sessions WHERE id = ?', (session['id'],))
            db.commit()
            return jsonify({'error': 'Session expired'}), 401

        g.user_id = session['user_id']
        g.session_id = session['id']
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            db = get_db()
            user = db.execute('SELECT role FROM users WHERE id = ?', (g.user_id,)).fetchone()
            if user is None or user['role'] != role:
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/auth/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = str(data['username']).strip()
    password = str(data['password'])

    if len(username) < 3 or len(username) > 32:
        return jsonify({'error': 'Username must be 3-32 chars'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password must be at least 8 chars'}), 400

    db = get_db()
    try:
        pw_hash = hash_password(password)
        db.execute('INSERT INTO users (username, password_hash) VALUES (?, ?)',
                   (username, pw_hash))
        db.commit()
        return jsonify({'message': 'User created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    db = get_db()
    user = db.execute('SELECT id, password_hash FROM users WHERE username = ?',
                      (str(data['username']),)).fetchone()

    if user is None or not verify_password(user['password_hash'], str(data['password'])):
        return jsonify({'error': 'Invalid credentials'}), 401

    token_str, token_id = generate_session_token()
    token_hash = compute_token_hash(token_str)
    expires_at = time.time() + 3600  # 1 hour

    db.execute('INSERT INTO sessions (id, user_id, token_hash, created_at, expires_at) VALUES (?, ?, ?, ?, ?)',
               (token_id, user['id'], token_hash, time.time(), expires_at))
    db.commit()

    return jsonify({'token': token_str, 'expires_in': 3600}), 200

@app.route('/api/auth/logout', methods=['POST'])
@require_auth
def logout():
    db = get_db()
    db.execute('DELETE FROM sessions WHERE id = ?', (g.session_id,))
    db.commit()
    return jsonify({'message': 'Logged out'}), 200

@app.route('/api/user/profile', methods=['GET'])
@require_auth
def get_profile():
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?', (g.user_id,)).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify({'id': user['id'], 'username': user['username'], 'role': user['role']})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role FROM users').fetchall()
    db.execute('INSERT INTO audit_log (user_id, action, resource, timestamp) VALUES (?, ?, ?, ?)',
               (g.user_id, 'list_users', '/api/admin/users', time.time()))
    db.commit()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/sessions', methods=['GET'])
@require_auth
@require_role('admin')
def list_sessions():
    db = get_db()
    sessions = db.execute(
        'SELECT s.id, s.user_id, u.username, s.created_at, s.expires_at '
        'FROM sessions s JOIN users u ON s.user_id = u.id'
    ).fetchall()
    return jsonify([dict(s) for s in sessions])

